#!/usr/bin/env bun
/**
 * The Jekyll sidebar's navbar, written by the SAME renderer every mounted and
 * generated page uses.
 *
 * @covers none — this asks whether a GENERATED INCLUDE is current, not
 * whether a declared graph is well-formed. It reads `docs/_data/harness.json`,
 * which is itself generated by `docs:harness` from the layer declarations,
 * so the graph question is asked there. `none` rather than silence, because
 * `audit:coverage` counts an unstated gate as a gap.
 *
 * `nav_footer_custom.html` is a one-line `{% include %}` of what this writes;
 * the template composes no markup at all, so the sidebar and the rail cannot
 * disagree about what a harness row contains.
 *
 * ## A generated INCLUDE rather than an injection pass
 *
 * `rail-standalone-pages.ts` injects the rail into finished HTML, which is
 * right for a page Jekyll copied through verbatim. These pages already have
 * the theme's `<nav id="site-nav">`, and the harness tabs belong INSIDE
 * `.side-bar`; `nav_footer_custom` is just-the-docs' own extension point
 * there. `_includes/generated/todo-listing.html` is the precedent for the
 * shape: a TypeScript generator, a committed artefact, a `--check` gate, and
 * Liquid `relative_url` filters in the output.
 *
 * ## The one thing the renderer cannot decide
 *
 * A viewer declared `publish: "staging-only"` is a LINK on a staging preview
 * and a NOTE on the canonical deploy. This file is COMMITTED, and
 * `docs/_data/harness.json` is the same bytes on both deploys (`--staging` is
 * passed to `compose-docs.ts` only); the only thing that knows is
 * `site.data.build.staging_slug`, read at Jekyll time. So the GENERATOR emits
 * one Liquid conditional around two models, one per deploy, each rendered by
 * the same function, and the renderer stays free of Liquid. Re-weigh the
 * duplication if many viewers become staging-only.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

import { checkoutRootFor, siteDirFor } from "../schemas/kg/cat-harness.js";
import { readPathAt, writePathAt } from "./lib/layer-output.ts";
import { graphTypologyRowDecor } from "./lib/graph-typology-nav.js";
import { kindTitle } from "./lib/nav-label.js";
import { navMarkFields, type HarnessMark } from "./lib/harness-mark.js";
import { jekyllNavPages, pagesNav } from "./lib/jekyll-pages-nav.ts";
import {
  GROUP_GLYPHS,
  RAIL_SECTION_LABELS,
  navbarOpenInputHtml,
  navbarRegionsHtml,
  type NavGroup,
  type NavItem,
  type NavbarModel,
} from "./lib/navbar.js";
import { HARNESS_ROOT } from "./lib/roots.ts";

// THE SITE ROOT IS ASKED FOR, never written down. `site-dir-single-answer`
// refuses the literal in source, and rightly: this generator writes into the
// site and a second copy of that string is a second answer to where the site
// is. It caught this file on its first run.
// The layer this generator belongs to, found by its declaration: in the
// monorepo `<repo>/cat-harness`, standalone the repository root (bean `uxn1`).
// The site is the harness's, and this script moved out of it (bean 70lx).
const INSTANCE = HARNESS_ROOT;
const SITE = join(INSTANCE, siteDirFor(INSTANCE));
/**
 * The checkout holding the layer. Where it MOUNTS cat-harness, this
 * generator's computed files live at the layer's output root rather than in
 * the pinned mount (bean `cat-tools-sm8r`, item 4, step 4): reads go through
 * `readPathAt` (the output root, else the pinned copy), writes through
 * `writePathAt`. In cat-harness's own checkout both are the site's own path.
 */
const CHECKOUT = checkoutRootFor(INSTANCE);
const DATA = readPathAt(CHECKOUT, join(SITE, "_data", "harness.json"));
const OUT = join(SITE, "_includes", "generated", "navbar-footer.html");

/**
 * The shape this reads out of `harness.json`.
 *
 * Declared structurally rather than imported from `harness-tiles.ts` on
 * purpose: this consumes the PUBLISHED artefact, and a type imported from the
 * producer would make a field look present here that the writer had stopped
 * emitting. The gate that catches a real mismatch is `docs:harness:check`,
 * which regenerates the data.
 */
interface Visualisation {
  kind: string;
  label?: string;
  sameAs?: string;
  path?: string | null;
  note?: string;
  stagingOnly?: true;
}
export interface Harness {
  name: string;
  title?: string;
  label?: string;
  href?: string;
  tone?: number;
  mark?: HarnessMark | null;
  instantiated?: boolean;
  visualisations?: Visualisation[];
  needs?: string[];
}

/**
 * The harness rows for an IG REPOSITORY'S OWN SITE (#2235 F1), the same view
 * the rail's `--instance` gives a page it injects into (`instanceHarnesses`):
 * this layer first, then what it needs, transitively, and nothing else.
 *
 * The rows are the main site's (`docs/_data/harness.json`), so their paths
 * are the main site's. On this site the layer IS the root: a path under
 * `/<instance>/` becomes the same path at `/`; every other path is the main
 * site's page and becomes an absolute URL under `linkRoot`, which Jekyll's
 * `relative_url` leaves as written.
 */
export function instanceView(harnesses: readonly Harness[], instance: string, linkRoot: string): Harness[] {
  const byName = new Map(harnesses.map((h) => [h.name, h]));
  const reach = new Set([instance]);
  for (const queue = [instance]; queue.length > 0; ) {
    for (const n of byName.get(queue.shift()!)?.needs ?? []) {
      if (reach.has(n)) continue;
      reach.add(n);
      queue.push(n);
    }
  }
  const root = linkRoot.replace(/\/$/, "");
  const own = `/${instance}/`;
  const map = (p: string | null | undefined): string | undefined => {
    if (!p) return undefined;
    if (/^[a-z][a-z0-9+.-]*:/i.test(p)) return p;
    if (p === own.slice(0, -1) || p.startsWith(own)) return `/${p.slice(own.length)}`;
    return `${root}${p.startsWith("/") ? "" : "/"}${p}`;
  };
  return harnesses
    .filter((h) => reach.has(h.name))
    .sort((a, b) => (a.name === instance ? -1 : b.name === instance ? 1 : 0))
    .map((h) => {
      const href = h.name === instance ? "/" : map(h.href);
      const { href: _drop, ...rest } = h;
      return {
        ...rest,
        ...(href ? { href } : {}),
        instantiated: true,
        visualisations: (h.visualisations ?? []).map((v) => {
          const { path: _p, ...vr } = v;
          const path = map(v.path);
          return path ? { ...vr, path } : vr;
        }),
      };
    });
}

/**
 * One harness's own graphs, as rows nested under it.
 *
 * `staging` says which deploy is being rendered, and it changes exactly one
 * thing: whether a staging-only viewer is reachable. Everything else about the
 * row is the same on both, which is why the models differ by a boolean rather
 * than by construction.
 *
 * **A kind with no path is rendered, not dropped** — `pb04`, and the rule the
 * rest of the navbar follows. A declared graph with no published viewer is a
 * FINDING, and hiding it would answer "what is in this harness" with silence.
 * `harness-tiles.ts` has already worded the reason; this picks none of them.
 */
function graphRows(h: Harness, staging: boolean): NavItem[] {
  // ONE NAME PER DESTINATION (bean `ob3m` finding 6): the row says the label
  // `harness-tiles.ts` gave it, never the bare kind word, and a kind whose page
  // is another kind's row (`sameAs`) is not listed a second time.
  return (h.visualisations ?? []).filter((v) => v.sameAs === undefined).map((v) => {
    const label = v.label ?? kindTitle(v.kind);
    const withheld = v.stagingOnly === true && !staging;
    // The same distinct glyph and full accessible name the rail gives a kind
    // row (bean `yag0`) — one answer, from `lib/graph-typology-nav.ts`.
    // The kind's HUE is left out here: the sidebar paints these small marks
    // on its own neutral chip in the page's ink, and a dark tone behind a
    // dark-ink glyph would lose contrast. The shape and the words carry it.
    const { tone: _tone, ...decor } = graphTypologyRowDecor(v.kind, h.label ?? h.title ?? h.name);
    if (v.path && !withheld) return { href: v.path, label, ...decor };
    const note = withheld ? "staging only" : v.note;
    return { label, ...decor, ...(note ? { note } : {}) };
  });
}

/** One harness row: its mark, its label, its ⚙, and its graphs. */
function harnessRow(h: Harness, staging: boolean): NavItem {
  const label = h.label ?? h.title ?? h.name;
  const kids = graphRows(h, staging);
  return {
    ...(h.href ? { href: h.href } : {}),
    label,
    // The row's resolved mark — image or glyph — read the one way every
    // navbar surface reads it (bean `2vpn`, `lib/harness-mark.ts`).
    ...navMarkFields(h.mark, h.tone),
    // The ⚙ opens the glass's Harnesses panel with this harness chosen (#1146).
    // `docs-ui.js` handles it by delegation; with no script it does nothing and
    // the row still works.
    action: {
      data: "data-fa-harness-config",
      value: h.name,
      label: `Configuration of ${label}`,
      glyph: "⚙︎",
    },
    ...(kids.length > 0 ? { children: kids } : {}),
  };
}

/**
 * The model for one deploy.
 *
 * **No `graphs`** — the theme's own `<nav id="site-nav">` owns the middle
 * region on this surface, and an empty disclosure there would be a second,
 * emptier answer to the same question.
 *
 * **Only the INSTANTIATED harnesses.** The owner, 2026-09-22: *"get rid of
 * dependencies."* A dependency that is not instantiated here publishes no folio
 * of its own to reach; what it contributes arrives through the layers that
 * do appear, which is what inheritance means.
 *
 * **Closed on arrival** — *"harnesses start closed"* — and the count on the
 * summary still says how many there are, so folded is not hidden.
 */
function model(
  harnesses: Harness[],
  title: string,
  staging: boolean,
  openControl: "input" | "labels",
  fshGuts: boolean,
  pages?: readonly NavItem[],
): NavbarModel {
  const shown = harnesses.filter((h) => h.instantiated === true);
  const group: NavGroup = {
    label: RAIL_SECTION_LABELS.harnesses,
    icon: "H",
    glyphPath: GROUP_GLYPHS.harnesses,
    items: shown.map((h) => harnessRow(h, staging)),
    collapsible: true,
  };
  return {
    instance: title,
    hrefs: "liquid",
    openControl,
    // The theme's `.site-title` avatar IS the header here (#1757).
    head: "none",
    // The site's page tree, server-built (owner, 2026-10-15, "folio rail
    // everywhere"). Given only with `--pages`: while the theme's own
    // `site-nav` is on the page, a second copy here would be the tree twice.
    ...(pages && pages.length > 0 ? { pages: { label: RAIL_SECTION_LABELS.pages, icon: "P", glyphPath: GROUP_GLYPHS.pages, items: pages, collapsible: true, open: false } } : {}),
    ...(shown.length > 0 ? { harnesses: group } : {}),
    // fsh-guts in the FIXED top (#1925, owner 2026-10-02: *"also add fsh-guts
    // icon to LHS top navbar"*), only when this layer DECLARES the
    // fsh-guts tile: a control for a trashcan nobody declared is a promise
    // with nothing behind it.
    ...(fshGuts ? { fshGuts: { label: "fsh-guts, discarded items" } } : {}),
    // No home row (owner, 2026-10-30: "dont need home on bottomof harnes
    // navbars"): the header's mark and name are the link to the landing page.
  };
}

const BANNER =
  "<!-- GENERATED by cat-harness/scripts/gen-navbar-include.ts. Do not hand-edit: " +
  "`bun run cat navbar:include` rewrites it, and `--check` fails the build if it is stale. -->";

/**
 * The file, Liquid control flow and all.
 *
 * The control flow is written HERE, by a generator, rather than in the template
 * — which is what lets `nav_footer_custom.html` be a single `{% include %}`
 * that composes not one tag. Both conditionals ask a question about the BUILD
 * that no renderer can answer:
 *
 * - `fa_nav_copy` — just-the-docs renders this extension point TWICE per page,
 *   once inside `.side-bar` and once in a `.d-md-none` block outside it. With
 *   the input in both, `id="fa-nav-open"` appeared twice on 429 of 1,283 pages
 *   (`uknu`). A Liquid `assign` inside an include sets the PAGE's context, so
 *   the counter survives from the first copy to the second and resets per page.
 * - `staging_slug` — which deploy this is. `head_custom.html` writes the same
 *   value into `fa-staging`, so the template and the client ask one question.
 *
 * `default:` collapses nil and empty, which are the same answer here: a build
 * that cannot say it is a preview is treated as canonical, which is the safe
 * direction and the one `isStagingPreview` already takes.
 */
export function render(harnesses: Harness[], title: string, fshGuts = false, pages?: readonly NavItem[]): string {
  const region = (staging: boolean): string =>
    navbarRegionsHtml(model(harnesses, title, staging, "labels", fshGuts, pages));
  return (
    `${BANNER}\n` +
    `{%- assign fa_nav_copy = fa_nav_copy | default: 0 | plus: 1 -%}\n` +
    `{%- if fa_nav_copy == 1 -%}${navbarOpenInputHtml()}{%- endif -%}\n` +
    `{%- assign _fa_staging = site.data.build.staging_slug | default: '' -%}\n` +
    `{%- if _fa_staging == '' -%}\n${region(false)}\n{%- else -%}\n${region(true)}\n{%- endif -%}\n`
  );
}

function main(): void {
  const check = process.argv.includes("--check");
  const data = JSON.parse(readFileSync(DATA, "utf-8")) as {
    harnesses?: Harness[];
    title?: string;
    tiles?: { id?: string }[];
  };
  // fsh-guts is NOT emitted into `.fa-nav-top` any more: the owner put it in
  // the declared icon row, "with the others" (2026-10-02, #1925), which
  // `mountNavIconRow` draws from `navbarIcons`. One placement, not two.
  // `--instance <name> --link-root <main site URL> [--title <label>] [--out <file>]`:
  // the navbar of an IG repository's own site (#2235 F1). Written into that
  // site's composed shell, never over the committed include.
  const argv = process.argv;
  const opt = (f: string) => (argv.includes(f) ? argv[argv.indexOf(f) + 1] : undefined);
  // `--pages <site source dir>`: the site's page tree as the rail's "Pages"
  // section, read from the same front matter the theme reads
  // (`lib/jekyll-pages-nav.ts`). Hrefs are site-absolute and go through
  // `relative_url` like every other row here.
  const pagesDir = opt("--pages");
  const pages = pagesDir ? pagesNav(jekyllNavPages(pagesDir), { locale: opt("--locale") ?? "en" }) : undefined;
  if (pages?.orphans.length) console.warn(`gen-navbar-include: ${pages.orphans.length} page(s) name a parent no listed page has; kept at the top level: ${pages.orphans.slice(0, 5).join(", ")}`);
  const instance = opt("--instance");
  if (instance) {
    const linkRoot = opt("--link-root");
    const out = opt("--out");
    if (!linkRoot || !out) {
      console.error("gen-navbar-include: --instance needs --link-root and --out (the shell's _includes/generated/navbar-footer.html)");
      process.exit(2);
    }
    const rows = instanceView(data.harnesses ?? [], instance, linkRoot);
    if (!rows.some((h) => h.name === instance)) {
      console.error(`gen-navbar-include: no harness named ${instance} in ${DATA}`);
      process.exit(2);
    }
    mkdirSync(dirname(out), { recursive: true });
    writeFileSync(out, render(rows, opt("--title") ?? instance, false, pages?.items));
    console.log(`wrote ${out} — ${instance}'s own navbar: ${rows.map((h) => h.name).join(", ")}`);
    return;
  }
  const next = render(data.harnesses ?? [], data.title ?? "folio-assistant", false, pages?.items);

  let current: string | undefined;
  try {
    current = readFileSync(readPathAt(CHECKOUT, OUT), "utf-8");
  } catch {
    current = undefined;
  }
  if (current === next) {
    console.log(`navbar include up to date — ${(data.harnesses ?? []).filter((h) => h.instantiated).length} instantiated harness(es)`);
    return;
  }
  if (check) {
    console.error("docs/_includes/generated/navbar-footer.html is stale — run `bun run cat navbar:include` and commit");
    process.exit(1);
  }
  const at = writePathAt(CHECKOUT, OUT);
  mkdirSync(dirname(at), { recursive: true });
  writeFileSync(at, next);
  console.log(`wrote ${at}`);
}

// Guarded so a test can import `render` without rewriting the committed include.
if (import.meta.main) main();
